examples.template:
List(orders.indices, id: \.self) { index in
    Button(orders[index].id) { selected = index }
        .listRowBackground(Color.clear)
}
.inspector(isPresented: isShown) {
    if let index = selected {
        VStack(alignment: .leading, spacing: 0) {
            HStack(spacing: MonarchTokens.Space.space2) {
                MonarchButton("Previous", systemImage: "chevron.up", variant: .ghost, size: .sm, isIconOnly: true) { selected = index - 1 }
                    .disabled(index == 0)
                MonarchButton("Next", systemImage: "chevron.down", variant: .ghost, size: .sm, isIconOnly: true) { selected = index + 1 }
                    .disabled(index == orders.count - 1)
                Text("\(index + 1) of \(orders.count)")
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
                Spacer(minLength: 0)
                Button("Open full record") {}
                    .buttonStyle(.monarchLink(.inline))
                    .monarchTextStyle(.bodySmall)
                MonarchButton("Close", systemImage: "xmark", variant: .ghost, size: .sm, isIconOnly: true) { selected = nil }
            }
            .padding(MonarchTokens.Space.space3)
            MonarchDivider()
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space1) {
                Text(orders[index].id).monarchTextStyle(.heading).foregroundStyle(theme.colors.textDefault)
                Text(orders[index].status).monarchTextStyle(.body).foregroundStyle(theme.colors.textMuted)
                Text("Total " + orders[index].total)
                    .monarchTextStyle(.body)
                    .foregroundStyle(theme.colors.textDefault)
                    .padding(.top, MonarchTokens.Space.space4)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(MonarchTokens.Space.space4)
            Spacer(minLength: 0)
            MonarchDivider()
            HStack {
                Spacer(minLength: 0)
                MonarchButton({{footer}}, variant: .primary) {}
            }
            .padding(MonarchTokens.Space.space3)
            .background(theme.colors.bgSubtle)
        }
        .presentationDetents([.medium, .large])
        .inspectorColumnWidth(min: 280, ideal: 360, max: 480)
    }
}
.listStyle(.plain)
.scrollContentBackground(.hidden)
.monarchCanvas()

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
struct Order {
    let id: String
    let status: String
    let total: String
}

@State private var selected: Int? = {{selected}}

private let orders = [
    Order(id: {{orders.0.id}}, status: {{orders.0.status}}, total: {{orders.0.total}}),
    Order(id: {{orders.1.id}}, status: {{orders.1.status}}, total: {{orders.1.total}}),
    Order(id: {{orders.2.id}}, status: {{orders.2.status}}, total: {{orders.2.total}}),
]

private var isShown: Binding<Bool> {
    Binding(get: { selected != nil }, set: { if !$0 { selected = nil } })
}

